final class LineageSchemaTwoFixtureTests: XCTestCase {
    func testFixtureLiteralsAreUnedited() {
        let literals = [
            "fatconv98ContStep6093": LineageSchemaTwoFixtures.fatconv98ContStep6093,
            "segResumeCheckSeg1Step1000": LineageSchemaTwoFixtures.segResumeCheckSeg1Step1000,
        ]
        XCTAssertEqual(Set(literals.keys), Set(LineageSchemaTwoFixtures.pinnedSHA256.keys))
        for (name, text) in literals {
            let digest = SHA256.hash(data: Data(text.utf8)).map { String(format: "%02x", $0) }.joined()
            XCTAssertEqual(digest, LineageSchemaTwoFixtures.pinnedSHA256[name], name)
        }
    }
